        "fused_moe_kernel_gptq_awq": "@triton.jit\ndef fused_moe_kernel_gptq_awq(\n        # Pointers to matrices\n        a_ptr,\n        b_ptr,\n        c_ptr,\n        b_scale_ptr,\n        b_zp_ptr,\n        topk_weights_ptr,\n        sorted_token_ids_ptr,\n        expert_ids_ptr,\n        num_tokens_post_padded_ptr,\n        # Matrix dimensions\n        N: tl.constexpr,\n        K: tl.constexpr,\n        EM,\n        num_valid_tokens,\n        # The stride variables represent how much to increase the ptr by when\n        # moving by 1 element in a particular dimension. E.g. `stride_am` is\n        # how much to increase `a_ptr` by to get the element one row down\n        # (A has M rows).\n        stride_am,\n        stride_ak,\n        stride_be,\n        stride_bk,\n        stride_bn,\n        stride_cm,\n        stride_cn,\n        stride_bse,\n        stride_bsk,\n        stride_bsn,\n        stride_bze,\n        stride_bzk,\n        stride_bzn,\n        block_k_diviable: tl.constexpr,\n        group_size: tl.constexpr,\n        # Meta-parameters\n        BLOCK_SIZE_M: tl.constexpr,\n        BLOCK_SIZE_N: tl.constexpr,\n        BLOCK_SIZE_K: tl.constexpr,\n        GROUP_SIZE_M: tl.constexpr,\n        MUL_ROUTED_WEIGHT: tl.constexpr,\n        top_k: tl.constexpr,\n        compute_type: tl.constexpr,\n        has_zp: tl.constexpr,\n        use_int4_w4a16: tl.constexpr,\n        use_int8_w8a16: tl.constexpr):\n    \"\"\"\n    Implements the fused computation for a Mixture of Experts (MOE) using\n    token and expert matrices with GPTQ/AWQ quantization.\n    \n    For GPTQ/AWQ quantization with group-wise quantization:\n    - Weights are quantized per group of size `group_size`\n    - Scales are per group: shape depends on quantization format\n    - Zero points (optional): per group for asymmetric quantization\n    \"\"\"\n    # -----------------------------------------------------------\n    # Map program ids `pid` to the block of C it should compute.\n    pid = tl.program_id(axis=0)\n    num_pid_m = tl.cdiv(EM, BLOCK_SIZE_M)\n    num_pid_n = tl.cdiv(N, BLOCK_SIZE_N)\n    num_pid_in_group = GROUP_SIZE_M * num_pid_n\n    group_id = pid // num_pid_in_group\n    first_pid_m = group_id * GROUP_SIZE_M\n    group_size_m = min(num_pid_m - first_pid_m, GROUP_SIZE_M)\n    pid_m = first_pid_m + ((pid % num_pid_in_group) % group_size_m)\n    pid_n = (pid % num_pid_in_group) // group_size_m\n\n    # ----------------------------------------------------------\n    # Create pointers for the first blocks of A and B.\n    num_tokens_post_padded = tl.load(num_tokens_post_padded_ptr)\n    if pid_m * BLOCK_SIZE_M >= num_tokens_post_padded:\n        return\n    offs_token_id = pid_m * BLOCK_SIZE_M + tl.arange(0, BLOCK_SIZE_M).to(\n        tl.int64)\n    offs_token = tl.load(sorted_token_ids_ptr + offs_token_id)\n    token_mask = offs_token < num_valid_tokens\n\n    offs_bn = (pid_n * BLOCK_SIZE_N +\n               tl.arange(0, BLOCK_SIZE_N).to(tl.int64)) % N\n    offs_k = tl.arange(0, BLOCK_SIZE_K)\n    a_ptrs = a_ptr + (offs_token[:, None] // top_k * stride_am +\n                      offs_k[None, :] * stride_ak)\n\n    off_experts = tl.load(expert_ids_ptr + pid_m).to(tl.int64)\n    \n    # Weight pointers - weights are already unpacked for the kernel\n    # The unpacking happens in the weight loading phase\n    b_ptrs = b_ptr + off_experts * stride_be + (offs_k[:, None] * stride_bk +\n                                                offs_bn[None, :] * stride_bn)\n    \n    # For group-wise quantization, scales and zero points have different shapes\n    # Based on the invoke_fused_moe_kernel call, B_scale has ndim == 3 for GPTQ/AWQ\n    # Scales shape: [E, N//group_size, K//group_size]\n    offs_bn_group = offs_bn // group_size\n    offs_k_group = offs_k // group_size\n    \n    # Scale pointers\n    b_scale_ptrs = (b_scale_ptr + off_experts * stride_bse +\n                    offs_bn_group[None, :] * stride_bsn + \n                    offs_k_group[:, None] * stride_bsk)\n    \n    # Zero point pointers if available\n    if has_zp:\n        b_zp_ptrs = (b_zp_ptr + off_experts * stride_bze +\n                     offs_bn_group[None, :] * stride_bzn + \n                     offs_k_group[:, None] * stride_bzk)\n\n    # -----------------------------------------------------------\n    # Iterate to compute a block of the C matrix.\n    accumulator = tl.zeros((BLOCK_SIZE_M, BLOCK_SIZE_N), dtype=tl.float32)\n\n    for k in range(0, tl.cdiv(K, BLOCK_SIZE_K)):\n        # Load the next block of A\n        a = tl.load(a_ptrs,\n                    mask=token_mask[:, None] &\n                    (offs_k[None, :] < K - k * BLOCK_SIZE_K),\n                    other=0.0)\n        \n        # Load quantized weights\n        # For GPTQ/AWQ, weights are stored as int8/int4 but loaded as int8\n        b_quantized = tl.load(b_ptrs,\n                              mask=offs_k[:, None] < K - k * BLOCK_SIZE_K,\n                              other=0)\n        \n        # Load scales for this block\n        b_scale = tl.load(b_scale_ptrs,\n                          mask=offs_k[:, None] < K - k * BLOCK_SIZE_K,\n                          other=1.0)\n        \n        # Dequantize weights\n        if use_int4_w4a16 or use_int8_w8a16:\n            # Convert to float32, apply scale, then convert to compute_type\n            b_dequantized = b_quantized.to(tl.float32) * b_scale\n            \n            # Apply zero points if available\n            if has_zp:\n                b_zp = tl.load(b_zp_ptrs,\n                               mask=offs_k[:, None] < K - k * BLOCK_SIZE_K,\n                               other=0)\n                b_dequantized = b_dequantized - b_zp.to(tl.float32) * b_scale\n            \n            # Convert to compute type for the dot product\n            b_dequantized = b_dequantized.to(compute_type)\n        else:\n            # Should not happen for GPTQ/AWQ\n            b_dequantized = b_quantized\n        \n        # Accumulate along the K dimension\n        accumulator += tl.dot(a, b_dequantized)\n        \n        # Advance the ptrs to the next K block.\n        a_ptrs += BLOCK_SIZE_K * stride_ak\n        b_ptrs += BLOCK_SIZE_K * stride_bk\n        # Scales and zero points advance by group_size in K dimension\n        b_scale_ptrs += (BLOCK_SIZE_K // group_size) * stride_bsk\n        if has_zp:\n            b_zp_ptrs += (BLOCK_SIZE_K // group_size) * stride_bzk\n\n    if MUL_ROUTED_WEIGHT:\n        moe_weight = tl.load(topk_weights_ptr + offs_token,\n                             mask=token_mask,\n                             other=0)\n        accumulator = accumulator * moe_weight[:, None]\n    \n    accumulator = accumulator.to(compute_type)\n    \n    # -----------------------------------------------------------\n    # Write back the block of the output\n    offs_cn = pid_n * BLOCK_SIZE_N + tl.arange(0, BLOCK_SIZE_N)\n    c_ptrs = c_ptr + stride_cm * offs_token[:, None] + stride_cn * offs_cn[\n        None, :]\n    c_mask = token_mask[:, None] & (offs_cn[None, :] < N)\n    tl.store(c_ptrs, accumulator, mask=c_mask)"
